using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Tools available to the agent
// ---------------------------------------------------------------------------

/// <summary>Simulated web search tool the agent can invoke.</summary>
static class WebSearchTool
{
    [Description("Searches the web for the given query and returns a list of result snippets.")]
    public static string Search([Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching the web for: \"{query}\"");
        Console.ResetColor();

        // Simulated search results keyed by broad topic keywords.
        var results = new List<string>();

        if (query.Contains("quantum computing", StringComparison.OrdinalIgnoreCase))
        {
            results.AddRange(
            [
                "Quantum computing uses qubits that leverage superposition and entanglement to perform parallel computations, potentially solving certain problems exponentially faster than classical computers. — Nature Reviews Physics, 2025",
                "IBM unveiled its 1,121-qubit Condor processor in late 2023 and plans modular systems exceeding 100,000 qubits by 2033. Google's Willow chip demonstrated below-threshold error correction in 2024. — IEEE Spectrum",
                "Key applications include cryptography (Shor's algorithm threatens RSA), drug discovery via molecular simulation, optimization in logistics, and machine-learning acceleration. — MIT Technology Review",
                "Current challenges: qubit decoherence times remain short, error rates are high, and most hardware requires cooling to near absolute zero. Fault-tolerant quantum computing is estimated to be 5-15 years away. — Quanta Magazine"
            ]);
        }

        if (query.Contains("artificial intelligence", StringComparison.OrdinalIgnoreCase)
            || query.Contains("AI", StringComparison.Ordinal))
        {
            results.AddRange(
            [
                "Large language models (LLMs) like GPT-5 and Gemini Ultra 2 are pushing the boundaries of reasoning, code generation, and multimodal understanding. — arXiv, 2025",
                "AI agents that use tool-calling and chain-of-thought planning are emerging as the dominant paradigm for autonomous task completion. — Stanford HAI Annual Report 2025",
                "Regulatory frameworks such as the EU AI Act (effective 2025) classify AI systems by risk level and impose transparency obligations. — European Commission",
                "Concerns around AI safety include alignment, hallucination, deepfake misuse, and labor displacement. Ongoing research focuses on RLHF, constitutional AI, and interpretability. — DeepMind Safety Blog"
            ]);
        }

        if (query.Contains("renewable energy", StringComparison.OrdinalIgnoreCase)
            || query.Contains("clean energy", StringComparison.OrdinalIgnoreCase)
            || query.Contains("solar", StringComparison.OrdinalIgnoreCase))
        {
            results.AddRange(
            [
                "Global renewable energy capacity surpassed 4,000 GW in 2024, with solar PV accounting for 75 % of new additions. — International Energy Agency",
                "Perovskite-silicon tandem solar cells achieved a record 33.9 % efficiency in lab conditions. Commercialization expected by 2027. — NREL",
                "Battery storage deployments tripled year-over-year; lithium-iron-phosphate (LFP) chemistry now dominates due to lower cost and longer cycle life. — BloombergNEF",
                "Challenges remain in grid integration, long-duration storage, and supply-chain bottlenecks for critical minerals like lithium and cobalt. — World Economic Forum"
            ]);
        }

        if (results.Count == 0)
        {
            results.Add(
                $"Several recent articles discuss \"{query}\". Key themes include ongoing research, "
                + "industry adoption, and evolving regulatory landscapes. Please refine your query for more specific results.");
        }

        return JsonSerializer.Serialize(results);
    }
}

/// <summary>Note-taking tool the agent can use to collect findings.</summary>
static class NoteTool
{
    private static readonly List<(string Topic, string Content)> _notes = [];

    [Description("Saves a research note under a given topic heading.")]
    public static string SaveNote(
        [Description("Short topic heading for the note")] string topic,
        [Description("The note content to save")] string content)
    {
        _notes.Add((topic, content));
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved under \"{topic}\" ({content.Length} chars)");
        Console.ResetColor();
        return $"Note saved under \"{topic}\".";
    }

    [Description("Returns all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var grouped = _notes
            .GroupBy(n => n.Topic)
            .Select(g => $"## {g.Key}\n" + string.Join("\n", g.Select(n => $"- {n.Content}")));

        return string.Join("\n\n", grouped);
    }
}

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔬 AI Research Agent (.NET 10)     ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    // Fall back to a demo mode that exercises the tools without calling OpenAI.
    Console.WriteLine("ℹ️  OPENAI_API_KEY not set — running in demo mode.\n");
    RunDemo();
    return;
}

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.Search),
        AIFunctionFactory.Create(NoteTool.SaveNote),
        AIFunctionFactory.Create(NoteTool.GetNotes),
    ],
    ToolMode = ChatToolMode.Auto,
};

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient("gpt-4o-mini")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

Console.Write("Enter a research topic (or press Enter for default): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
    topic = "quantum computing";

Console.WriteLine($"\n🚀 Researching \"{topic}\"...\n");

List<ChatMessage> history =
[
    new(ChatRole.System,
        """
        You are a thorough research agent. When given a topic:
        1. Use the Search tool 2-3 times with varied queries to gather information.
        2. Use SaveNote to record key findings under descriptive topic headings.
        3. After gathering enough information, use GetNotes to review your notes.
        4. Finally, provide a well-structured summary to the user with sections and bullet points.
        Be concise but comprehensive.
        """),
    new(ChatRole.User, $"Please research the following topic and summarize your findings: {topic}")
];

var response = await client.GetResponseAsync(history, chatOptions);

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("\n═══════════════  Research Summary  ═══════════════\n");
Console.ResetColor();
Console.WriteLine(response.Text);

// ---------------------------------------------------------------------------
// Demo mode — exercises tools without an LLM
// ---------------------------------------------------------------------------

static void RunDemo()
{
    var topic = "quantum computing";
    Console.WriteLine($"🚀 Researching \"{topic}\" (demo mode)...\n");

    // Step 1 — search
    var searchResults = WebSearchTool.Search("quantum computing breakthroughs");
    var snippets = JsonSerializer.Deserialize<List<string>>(searchResults)!;

    // Step 2 — take notes
    foreach (var snippet in snippets)
    {
        var heading = snippet.Contains("qubit", StringComparison.OrdinalIgnoreCase) ? "Qubit Technology"
            : snippet.Contains("application", StringComparison.OrdinalIgnoreCase) ? "Applications"
            : snippet.Contains("challenge", StringComparison.OrdinalIgnoreCase) ? "Challenges"
            : "Overview";
        NoteTool.SaveNote(heading, snippet);
    }

    // Step 3 — retrieve notes
    Console.WriteLine();
    var notes = NoteTool.GetNotes();

    // Step 4 — summarize
    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("═══════════════  Research Summary  ═══════════════\n");
    Console.ResetColor();
    Console.WriteLine(notes);
    Console.WriteLine("\n✅ Demo complete. Set OPENAI_API_KEY to use the full AI agent.\n");
}

